__NUXT_JSONP__("/svetovy-cas/barbados", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{place:[{tld:".bb",name:"Barbados",area:430,population:287375,slug:g,id_continent:d,information_chatgpt:"\u003Cp\u003EBarbados je ostrov v Karibiku, který se nachází východně od ostrova Svatá Lucie. Je nejvýchodnějším ostrovem v Západní Indii a je známý svými bílými plážemi, tyrkysovými vodami a tropickým klimatem.\u003C\u002Fp\u003E\n\u003Cp\u003EHlavním městem Barbadosu je Bridgetown, který je také hlavním přístavem země. Město nabízí mnoho historických a kulturních památek, jako je například Garrison Historic Area, který byl zařazen na seznam světového dědictví UNESCO. Další zajímavou atrakcí je například muzeum Barbados Museum & Historical Society, které ukazuje historii a kulturu ostrova.\u003C\u002Fp\u003E\n\u003Cp\u003EBarbados je také znám svou bohatou flórou a faunou. Zdejší vody jsou domovem pro mnoho druhů ryb, želv a korálů. Ostrov také nabízí mnoho přírodních krás, jako jsou například Harrison's Cave, podzemní krasové jeskyně s podzemními řekami a vodopády. Pro milovníky rostlin je zajímavým místem Andromeda Botanic Gardens, kde se nachází mnoho druhů tropických rostlin.\u003C\u002Fp\u003E\n\u003Cp\u003EBarbados je také známý svou kuchyní, která je ovlivněna africkou, karibskou a britskou kuchyní. Mezi nejznámější místní speciality patří ryby a plody moře, jako je například mahi-mahi nebo krevety. Mezi další tradiční pokrmy patří flying fish, což je místní ryba, a cou-cou, což je pokrm z kukuřičné mouky a okra. \u003C\u002Fp\u003E\n\u003Cp\u003EBarbados je také známý svými festivalem a akcemi, jako je například Crop Over festival, který oslavuje konci sklizně cukrové třtiny a probíhá v létě. Během festivalu se konají různé akce, jako jsou taneční představení, průvody a soutěže.\u003C\u002Fp\u003E\n\u003Cp\u003EBarbados je tedy rájem pro milovníky pláží, historie, kultury a tropické přírody. Turisté sem mohou přijet na dovolenou nebo jako součást plavby po Karibiku.\u003C\u002Fp\u003E",currency_code:"BBD",currency_name:"barbadoský dolar",money_prices:[{name:"Taxi (cena za km)",value:4.5,date_update:a},{name:"Hlavní jídlo",value:50,date_update:a},{name:"Chleba",value:h,date_update:a},{name:"Mléko",value:i,date_update:a},{name:"Voda (500ml)",value:2.5,date_update:a},{name:"Espresso",value:8,date_update:a},{name:"Zmrzlina (jeden kopeček)",value:4,date_update:a},{name:"Pivo",value:6,date_update:a},{name:"Krabička cigaret",value:j,date_update:a},{name:"Bic Mac",value:20,date_update:a},{name:"Coca Cola (500ml)",value:i,date_update:a}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"112",date_update:e},{name:"Policie",value:"211",date_update:e},{name:"Hasiči",value:"311",date_update:e},{name:"Zdravotnická záchranná služba",value:"511",date_update:e}],phone_prefix:"+1-246",coordinates:[{latitude:"13.1939",longitude:"-59.5432"}],people_religion:[{name:"Křesťanství",value:"95.8%"},{name:"Bez vyznání",value:"2.5%"},{name:"Jiné",value:"1.7%"}],people_nationality:[{name:"černoši",value:"92,4%"},{name:"mulati",value:"3,1%"},{name:"běloši",value:"2,7%"},{name:"jiné",value:"1,8%"}],visitors_entry:[{name:"Občanský průkaz",value:"Občanský průkaz není platným cestovním dokladem pro vstup do Barbadosu. Je nutné mít platný cestovní pas.",date_update:c},{name:"Cestovní pas",value:"Pro vstup do Barbadosu je nutné mít platný cestovní pas, který platí minimálně po dobu pobytu na ostrově.",date_update:c},{name:"Vízum",value:"Pro občany České republiky a ostatních zemí Evropské unie není nutné vízum pro krátkodobý pobyt do 90 dnů. Pokud pobyt přesahuje 90 dnů, je nutné požádat o povolení k pobytu u Barbadoské imigrační kanceláře. Ostatní cizinci mohou mít odlišné požadavky na víza.",date_update:c},{name:"Očkování",value:"Pro vstup do Barbadosu není povinné očkování. Doporučuje se však očkování proti žluté zimnici pro osoby nad 1 rokem věku, pokud cestují z oblasti se vysokým rizikem nákazy.",date_update:c},{name:"Cestovní pojištění",value:"Cestovní pojištění není nutné, ale je silně doporučeno kvůli vysokým nákladům zdravotní péče na Barbadosu.",date_update:c},{name:"Bezpečnostní situace",value:"Bezpečnostní situace na Barbadosu je obecně klidná. Turisté by však měli být obezřetní, zejména v oblastech s vysokou kriminalitou, jako jsou Bridgetown a St. Michael Parish. Doporučuje se také pečlivě sledovat zpravodajství a místní doporučení.",date_update:c},{name:"Další informace",value:"Na Barbadosu se řídí levým provozem. Místní měna je barbadoský dolar, ale americký dolar je obecně přijímán většinou obchodů a turistických zařízení. Zvyklosti jsou obdobné jako v jiných karibských zemích, je vhodné oblékat se decentně a respektovat místní kulturu a tradice.",date_update:c}],type_place:k,id_image_cover:f,id_image_hero:f,id_city_main:161,affiliate:[{name:"booking",value:true}],mpz:"BB",alerts:b,zoom:[{google:10,booking:11}],ids_neighboring_countries:b,organization:b,apps:b,links:b,information_author:b,seo_tags:b,language_phrases:b,wall_sockets:b,id:j}],imagePlace:[{id:f,name:g,source:"\u002Fworld\u002Fstates\u002F",date_create:"2023-04-10T23:53:00.983932+00:00",type:k,author:"pixabay.com"}],placeContinent:[{id:d,slug:"severni-amerika",name:"Severní Amerika",area:24490000,population:589000000,population_density:24.04,number_states:23,information_chatgpt:"\u003Cp\u003ESeverní Amerika je třetím největším kontinentem na světě. Rozprostírá se od Arktického oceánu na severu až k Panama kanálu na jihu. Kontinent se skládá ze 23 nezávislých států, včetně Spojených států, Kanady a Mexika, a mnoha dalších závislých území, jako je Grónsko, Bermudy a Portoriko.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je známá svým pestrobarevným kulturním dědictvím, od původních obyvatel až po evropské osadníky a africké otroky. To se odráží v různorodosti jazyků, náboženství, kuchyně, hudby a tradic, které se na kontinentu nacházejí. \u003C\u002Fp\u003E\n\u003Cp\u003EMezi největší atrakce Severní Ameriky patří národní parky, jako jsou Yellowstone, Banff a Yosemite, které nabízejí ohromující přírodní krásy, jako jsou gejzíry, vodopády a divoká zvířata, včetně medvědů a losů. Mezi další populární turistické destinace patří města jako New York, San Francisco, Vancouver a Mexico City, která nabízejí různé zážitky a atrakce.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je také domovem mnoha kultur a tradic, včetně amerického fotbalu, baseballu a basketbalu, kanadského hokeje a mexického fotbalu. Navíc zde najdeme mnoho různých festivalů a oslav, jako například Día de los Muertos v Mexiku nebo Thanksgiving Day v USA a Kanadě.\u003C\u002Fp\u003E\n\u003Cp\u003EV západní části kontinentu najdeme nejvyšší horu Severní Ameriky, Mount McKinley, která se nachází v Aljašce. Východní část kontinentu pak tvoří rozsáhlé planiny, jako jsou Velká pláň a Floridská pláň. \u003C\u002Fp\u003E\n\u003Cp\u003EKlima Severní Ameriky se výrazně liší podle oblastí. Na severu a v oblastech vysokohorských pásem se vyskytují chladné a sněhové zimy, zatímco na jihu a na pobřeží Pacifiku jsou zimy mírnější. Celkově však kontinent nabízí mnoho slunečných a teplých dnů, zejména v letních měsících.\u003C\u002Fp\u003E\n\u003Cp\u003ENa kontinentu najdeme také mnoho různých druhů fauny a flóry. Mezi nejvíce známé zvířata patří medvědi, vlci, losi, bizoni, krokodýli a mnoho dalších. Severní Amerika má také rozmanitou flóru, včetně různých druhů stromů, květin a rostlin, jako jsou kaktusy a douglasky.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika má významnou roli ve světové ekonomice. Spojené státy jsou největší ekonomikou na světě, zatímco Kanada je jedním z největších světových výrobců surovin, jako je dřevo, zemní plyn a ropa. Mexiko je důležitým producentem automobilů, elektroniky a potravin. \u003C\u002Fp\u003E\n\u003Cp\u003ENavzdory tomu má Severní Amerika také mnoho výzev. Mezi největší problémy patří změna klimatu, nerovnost, přistěhovalectví a ochrana přírodních zdrojů. Zároveň však existuje mnoho iniciativ a organizací, které se snaží tyto problémy řešit a posilovat spolupráci mezi jednotlivými zeměmi kontinentu. \u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je fascinujícím kontinentem s mnoha přírodními krásami, kulturními tradicemi a ekonomickým vlivem na světovou scénu. Bez ohledu na to, zda se jedná o turistickou destinaci nebo oblast zájmu z hlediska vědy a průmyslu, Severní Amerika nabízí mnoho možností pro objevování a poznávání. \u003C\u002Fp\u003E",coordinates:[{latitude:47.497912,longitude:-100.540235}],type_place:"continent",id_image_cover:d,id_image_hero:d,zoom:[{google:2,booking:h}],information_author:b,seo_tags:b}]}],fetch:{},mutations:void 0}}("01-2021",null,"04-2023",1,"05-2023",25,"barbados",3,3.5,18,"state")));